### Terragrunt `dependency` Block Pattern (Required)

Platform values **must** be sourced through the `dependency.platform` block in Terragrunt configurations:

```hcl
# terragrunt.hcl — platform dependency

dependency "platform" {
  config_path = "../../acquire-tfstate"

  mock_outputs_allowed_terraform_commands = ["validate", "plan"]
  mock_outputs = {
    remote_tfstates = {
      account = {
        outputs = {
          vpc_id             = "vpc-00000000000000001"
          private_subnet_ids = ["subnet-00000000000000001", "subnet-00000000000000002"]
          eks_cluster_name   = "mock-cluster"
          oidc_provider_id   = "oidc.eks.us-east-1.amazonaws.com/id/MOCK"
        }
      }
    }
  }
}

inputs = {
  vpc_id             = dependency.platform.outputs.remote_tfstates["account"].outputs.vpc_id
  private_subnet_ids = dependency.platform.outputs.remote_tfstates["account"].outputs.private_subnet_ids
  eks_cluster_name   = dependency.platform.outputs.remote_tfstates["account"].outputs.eks_cluster_name
  oidc_provider_id   = dependency.platform.outputs.remote_tfstates["account"].outputs.oidc_provider_id
}
```

