### S3 Backend Configuration (Required)

```hcl
# common-includes.hcl — remote_state block

remote_state {
  backend = "s3"
  generate = {
    path      = "backend.tf"
    if_exists = "overwrite_terragrunt"
  }
  config = {
    bucket         = get_env("TG_STATE_BUCKET")       # Set by acquire-tfstate — REQUIRED
    key            = "${local.product_abr}/${local.environment}/${local.region}/terraform.tfstate"
    region         = local.region
    encrypt        = true                              # REQ-IAC-005-03a: AES256 — MUST be true
    dynamodb_table = get_env("TG_STATE_LOCK_TABLE")   # Set by acquire-tfstate — REQUIRED
  }
}
```

