### Variable Validation Pattern (Required)

Every `variables.tf` variable that receives a platform state output **must** include a `validation {}` block:

```hcl
# formations/aws/<name>/variables.tf

variable "vpc_id" {
  description = "VPC ID sourced from platform state via dependency.platform.outputs.remote_tfstates[\"account\"].outputs.vpc_id."
  type        = string
  default     = null

  validation {
    condition     = var.vpc_id != null && can(regex("^vpc-[0-9a-f]{17}$", var.vpc_id))
    error_message = "vpc_id must be a valid VPC ID (vpc-XXXXXXXXXXXXXXXXX, 17 hex chars). Ensure acquire-tfstate ran successfully. Source: dependency.platform.outputs.remote_tfstates[\"account\"].outputs.vpc_id"
  }
}

variable "private_subnet_ids" {
  description = "Private subnet IDs sourced from platform state. Minimum two for multi-AZ deployment."
  type        = list(string)
  default     = null

  validation {
    condition     = var.private_subnet_ids != null && length(var.private_subnet_ids) >= 2
    error_message = "private_subnet_ids must contain at least two subnet IDs (multi-AZ required). Ensure acquire-tfstate ran successfully. Source: dependency.platform.outputs.remote_tfstates[\"account\"].outputs.private_subnet_ids"
  }
}

variable "eks_cluster_name" {
  description = "EKS cluster name sourced from platform state."
  type        = string
  default     = null

  validation {
    condition     = var.eks_cluster_name != null && length(var.eks_cluster_name) > 0
    error_message = "eks_cluster_name must be non-null and non-empty. Ensure acquire-tfstate ran successfully. Source: dependency.platform.outputs.remote_tfstates[\"account\"].outputs.eks_cluster_name"
  }
}
```
